<?php
define('ANI_SMS_LOCAL_TEST',true);$_SERVER['REMOTE_ADDR']='127.0.0.1';
require __DIR__.'/bootstrap.php';
use AniSms\Infrastructure\Database;
use AniSms\Infrastructure\Queue;
use AniSms\Marketing\Subscribers;
use AniSms\Marketing\Campaigns;
use AniSms\Marketing\Module;
use AniSms\Security\Secrets;

$store=new Database($wpdb);$store->migrate();$store->migrate();
foreach(array('jobs','campaign_recipients','campaigns','consents','subscribers') as $table){$store->query("DELETE FROM {$store->table($table)}");}
add_filter('pre_wp_mail','__return_true');$http=0;add_filter('pre_http_request',function()use(&$http){++$http;return new WP_Error('blocked');},1);
update_option('ani_sms_modules',array('auth','marketing'));
$sub=new Subscribers($store);$queue=new Queue($store);$module=new Module($store,$queue);$module->boot();$campaigns=new Campaigns($store,$queue);$secrets=new Secrets();
$admin=get_user_by('login','ani_test_admin');
$phone='09127770001';$phone2='09127770002';
$user=wp_insert_user(array('user_login'=>'ani_marketing_'.bin2hex(random_bytes(5)),'user_pass'=>wp_generate_password(30),'user_email'=>'marketing-'.bin2hex(random_bytes(5)).'@example.invalid','role'=>'subscriber'));
$user2=wp_insert_user(array('user_login'=>'ani_marketing_'.bin2hex(random_bytes(5)),'user_pass'=>wp_generate_password(30),'role'=>'subscriber'));
ani_check(is_int($user)&&is_int($user2),'test subscribers created');
$normalized=AniSms\Support\Phone::normalize($phone);$normalized2=AniSms\Support\Phone::normalize($phone2);
$store->query($wpdb->prepare("DELETE FROM {$store->table('identities')} WHERE phone IN (%s,%s)",$normalized,$normalized2));
$store->insert('identities',array('phone'=>$normalized,'user_id'=>$user,'verified_at'=>time()));
$id=$sub->import($phone,'test');
$state=fn($id)=>$wpdb->get_row($wpdb->prepare("SELECT * FROM {$store->table('subscribers')} WHERE id=%d",$id),ARRAY_A);
$jobs=fn($id)=>$wpdb->get_results($wpdb->prepare("SELECT * FROM {$store->table('jobs')} WHERE subject=%s",'campaign:'.$id),ARRAY_A);
$draft=fn($tag='test',$more=array())=>$campaigns->create(array_merge(array('title'=>'Local campaign','body'=>'سلام {site_name}','tag'=>$tag,'line'=>'','scheduled'=>''),$more));
$approve=function($cid)use($campaigns,$admin){$p=$campaigns->preview($cid);$campaigns->approve($cid,$p['fingerprint'],true,$admin->ID);};
$drain=function()use($store,$queue){$store->query("UPDATE {$store->table('jobs')} SET available=0");$queue->drain();};
ani_check('pending'===$state($id)['state'],'import does not grant consent');
ani_check($id===$sub->import('+989127770001','ignored')&&'test'===$state($id)['tag'],'canonical dedup and import does not overwrite data');
$cid=$draft();ani_check(0===$campaigns->preview($cid)['count'],'pending excluded from audience');
ani_rejects(fn()=>$sub->consent($user,false,Subscribers::VERSION),'unchecked consent rejected');
ani_rejects(fn()=>$sub->consent($user,true,'old-version'),'old consent version rejected');
ani_rejects(fn()=>$sub->consent($user2,true,Subscribers::VERSION),'unverified mobile rejected');
ani_check($id===$sub->consent($user,true,Subscribers::VERSION),'explicit verified consent recorded');
$row=$state($id);$token=$secrets->decrypt($row['token']);
ani_check('consented'===$row['state']&&Subscribers::VERSION===$row['version']&&'account_form'===$row['source'],'source/version retained');
ani_check(!str_contains($row['phone'],$normalized)&&!str_contains($row['token'],$token),'phone and token encrypted');
ani_check(!str_contains($sub->url($row),'0912')&&strlen($token)===64,'random token link does not expose phone');
$evidence=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$store->table('consents')}");$sub->consent($user,true,Subscribers::VERSION);
ani_check($evidence===(int)$wpdb->get_var("SELECT COUNT(*) FROM {$store->table('consents')}"),'repeated consent form is idempotent');
$sub->tag($id,'changed');ani_check('changed'===$state($id)['tag']&&'consented'===$state($id)['state'],'group assignment preserves consent');$sub->tag($id,'test');
$preview=$campaigns->preview($cid);ani_check(1===$preview['count']&&str_contains($preview['text'],'{unsubscribe_url}'),'preview deduplicates and forces unsubscribe');
ani_rejects(fn()=>$campaigns->approve($cid,$preview['fingerprint'],false,$admin->ID),'explicit campaign confirmation required');
ani_rejects(fn()=>$campaigns->approve($cid,$preview['fingerprint'],true,$user),'subscriber cannot approve campaign');
$sub->suppress($id,false);ani_rejects(fn()=>$campaigns->approve($cid,$preview['fingerprint'],true,$admin->ID),'changed audience rejects stale approval');
$sub->import($phone,'test');ani_check('suppressed'===$state($id)['state'],'reimport never removes suppression');
$sub->consent($user,true,Subscribers::VERSION);$approve($cid);
ani_check(1===count($jobs($cid)),'approval snapshots one unique recipient');
ani_rejects(fn()=>$approve($cid),'duplicate approval rejected');
$campaigns->control($cid,'pause');$drain();ani_check('paused'===$jobs($cid)[0]['state']&&''!==$jobs($cid)[0]['payload'],'pause preserves encrypted job for resume');
update_option('ani_sms_modules',array('auth','marketing','queue-test'));$other=0;$queue->register('queue-test',function()use(&$other){++$other;return new AniSms\Provider\Result('simulated');});
$queue->enqueue(array('job_key'=>hash('sha256',random_bytes(32)),'module'=>'queue-test','subject'=>'test:fairness','sequence'=>0,'route'=>'test','mode'=>'local','phone_mask'=>'','available'=>0),array());$queue->drain();ani_check(1===$other,'paused campaign does not block other module jobs');$store->query("DELETE FROM {$store->table('jobs')} WHERE module='queue-test'");update_option('ani_sms_modules',array('auth','marketing'));
$campaigns->control($cid,'resume');$drain();ani_check('simulated'===$jobs($cid)[0]['state'],'resumed local campaign simulated');
ani_check('completed'===$campaigns->get($cid)['state'],'completed campaign state reconciled');
$message=$campaigns->message($campaigns->get($cid),$state($id));ani_check(!str_contains($message,'{site_name}')&&str_contains($message,'ani_sms_unsubscribe='),'message resolves allowed variables with opt-out URL');
$cid2=$draft();$approve($cid2);$current=$state($id);$sub->unsubscribe($secrets->decrypt($current['token']));$drain();
ani_check('cancelled'===$jobs($cid2)[0]['state'],'opt-out after enqueue cancels delivery');
$sub->consent($user,true,Subscribers::VERSION);$sub->unsubscribe($token);ani_check('consented'===$state($id)['state'],'old token cannot revoke a fresh opt-in');
$cid3=$draft();$approve($cid3);$campaigns->control($cid3,'cancel');$drain();ani_check('cancelled'===$jobs($cid3)[0]['state'],'campaign cancellation cancels queued work');
ani_rejects(fn()=>$draft('test',array('body'=>'Unknown {phone}')),'unknown variable rejected');
ani_rejects(fn()=>$draft('test',array('body'=>'<script>x</script>')),'HTML rejected');
ani_rejects(fn()=>$draft('test',array('scheduled'=>'2020-01-01T10:00')),'past schedule rejected');
ani_rejects(fn()=>$draft('test',array('scheduled'=>'2099-01-01T10:00')),'distant schedule rejected');
$future=$draft('test',array('scheduled'=>wp_date('Y-m-d\TH:i',time()+3600)) );$approve($future);$queue->drain();ani_check('queued'===$jobs($future)[0]['state'],'scheduled campaign not dispatched early');
$privacy=new AniSms\Marketing\Privacy($store);$email=get_user_by('id',$user)->user_email;ani_check(count($privacy->export($email)['data'])>0,'privacy export includes consent data');
$privacy->erase($email);$erased=$state($id);ani_check(''===$erased['phone']&&''===$erased['token']&&0===(int)$erased['user_id']&&'suppressed'===$erased['state'],'privacy erasure leaves minimum suppression only');
ani_check($id===$sub->import($phone,'test')&&'suppressed'===$state($id)['state'],'erased contact cannot be reconsented by import');
ani_check(0===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$store->table('consents')} WHERE subscriber_id=%d",$id)),'erasure removes consent history');
$sub->consent($user,true,Subscribers::VERSION);$new=$draft('');$approve($new);update_option('ani_sms_modules',array('auth'));$drain();ani_check('cancelled'===$jobs($new)[0]['state'],'module disable cancels queued marketing');
update_option('ani_sms_modules',array('auth','marketing'));
update_option('ani_sms_marketing_key_id','different-key');ani_rejects(fn()=>new Subscribers($store),'key rotation fails closed rather than bypassing suppression');update_option('ani_sms_marketing_key_id',$secrets->id());
$old=$draft();$store->query($wpdb->prepare("UPDATE {$store->table('campaigns')} SET created=0 WHERE id=%d",$old));$privacy->cleanup();ani_check(null===$campaigns->get($old),'old campaign bodies removed by retention cleanup');
ani_check(0===$http,'zero outbound HTTP in local marketing suite');
require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($user);wp_delete_user($user2);
echo 'Marketing checks: '.$GLOBALS['ani_checks']." passed; no HTTP or SMS\n";
